using System;using System.IO;using System.Text;using System.Windows.Forms;using THub.ACE8;
class Program {
 [STAThread]static int Main(string[] args){if(args.Length==0){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new OfflineWindow());return 0;}string report=null;for(int i=0;i<args.Length-1;i++)if(args[i]=="--report")report=args[i+1];try{string action=args[0];object result;if(action=="--self-test"){var payload=Engine.Payload();if(payload.Count!=18)throw new Exception("Payload count");foreach(var p in new[]{"../outside","/outside","C:/outside","Game/../../outside","Game\\outside","Game/.. /outside"}){bool rejected=false;try{Engine.PathFor(Path.GetTempPath(),p);}catch{rejected=true;}if(!rejected)throw new Exception("Unsafe path accepted");}if(Engine.SpaceEnough(1,2))throw new Exception("Space check");result=new{passed=true,payload_files=payload.Count,path_traversal_rejected=true,space_check_passed=true,game_launched=false};}else if(action=="--export-resources"){Engine.Export(args[1]);result=new{success=true,action="export"};}else{if(args.Length<3||Array.IndexOf(args,"--yes")<0)throw new Exception("CLI mutation requires explicit --yes");if(action=="--install")Engine.Install(args[1]);else if(action=="--uninstall")Engine.Uninstall(args[1]);else throw new Exception("Unknown action");result=new{success=true,action=action,game_launched=false};}if(report!=null)File.WriteAllText(report,Engine.Json.Serialize(result),Encoding.UTF8);return 0;}catch(Exception e){if(report!=null)File.WriteAllText(report,Engine.Json.Serialize(new{success=false,error=e.Message}),Encoding.UTF8);return 1;}}
}
